mapper.sql:
sc.deleted = 0

    AND sc.user_id = #{param.userId}


    AND sc.problem_id = #{param.problemId}


    AND sc.conversation_id = #{param.conversationId}


    AND (
        sc.conversation_id LIKE CONCAT('%', #{param.keyword}, '%')
        OR sc.message_content LIKE CONCAT('%', #{param.keyword}, '%')
    )
